		{2'd3, 1'b1, 9'h17A}: keymap = {2'd0, 7'd54};   // UPARROW
		{2'd3, 1'b0, 9'h17D}: keymap = {2'd0, 7'd67};   // HELP
		{2'd3, 1'b1, 9'h17D}: keymap = {2'd0, 7'd67};   // HELP
